-- Every Roadmap item is now a complete GeoCloud issue, status Open on Project #7 (#876–#916,
-- published 28/09 from the SCRUM/2026/ROADMAP.md text). This migration:
--   1. links the items RoadS already had to their new issue;
--   2. brings in the ROADMAP.md items RoadS didn't have yet, grouped by topic like the others,
--      plus two existing issues the ROADMAP points at (#222 rate limiting, #557 dormant modules);
--   3. queues each link ("modify") and each new item ("add") in roadmap_sync_queue, so the next
--      FrontlightS /update-roads writes the issue links into ROADMAP.md.
-- "CI com as quatro suítes" is left out: .github/workflows/ci.yml already runs all four suites on
-- every pull request.

-- 1. Links.
update public.roadmap_items set github_issue_url = 'https://github.com/Essencis-Labs/GeoCloudAI/issues/876', github_issue_number = 876, updated_at = now() where title = 'Sidebar recuado ao entrar em qualquer visualizador' and github_issue_url is null;
update public.roadmap_items set github_issue_url = 'https://github.com/Essencis-Labs/GeoCloudAI/issues/877', github_issue_number = 877, updated_at = now() where title = 'Página própria do visualizador, com filtros de região até caixa' and github_issue_url is null;
update public.roadmap_items set github_issue_url = 'https://github.com/Essencis-Labs/GeoCloudAI/issues/878', github_issue_number = 878, updated_at = now() where title = 'Título do nível corrido, com a data ao lado e a imagem do nível menor' and github_issue_url is null;
update public.roadmap_items set github_issue_url = 'https://github.com/Essencis-Labs/GeoCloudAI/issues/879', github_issue_number = 879, updated_at = now() where title = 'Accordion do menu lateral direito: deixar explícito que abre listagem' and github_issue_url is null;
